//! Tool-call ids, for the calls llama.cpp does not give one.
//!
//! # Why this exists at all
//!
//! Behind `llama-server` every tool call arrived with an id, so nothing in the
//! core ever had to think about it. That id was generated by the SERVER:
//! `gen_tool_call_id` lives in `vendor/llama.cpp/tools/server/server-common.cpp:113`,
//! which is upstream's server binary, and this port deliberately does not build
//! it. The library half does not fill the gap either: `to_json_oaicompat` emits
//! `id` only when the model produced one, and the line that would generate one
//! is commented out (`vendor/llama.cpp/common/chat.cpp:252-258`).
//!
//! So for every template whose tool-call syntax carries no id (which is most of
//! them, Qwen3.5's nested XML form included) the in-process engine gets an empty
//! id where the sidecar gave a real one.
//!
//! # Why an empty id is not a cosmetic problem
//!
//! The transcript replays each call on the assistant message and answers it with
//! a `tool` message keyed by `tool_call_id`. `llm::types::ToolCallRef` says what
//! happens when they do not match: the response "renders as an orphaned response
//! in the chat template, garbling every hop after it". So a missing id does not
//! fail; it quietly corrupts every turn after the first tool call.
//!
//! # Stability is the requirement, not uniqueness
//!
//! One call is streamed as several fragments sharing an index, and the consumer
//! reassembles by index. If the id were generated per fragment, the last one to
//! arrive would win and could disagree with what the model was told. So the id
//! is minted once when an index is first seen and remembered for the turn.

use std::collections::HashMap;

/// The ids assigned during one turn. One per turn: indices restart at zero on
/// the next one, and reusing this across turns would hand a new call the
/// previous turn's id.
#[derive(Debug, Default)]
pub struct ToolCallIds {
    assigned: HashMap<u32, String>,
}

impl ToolCallIds {
    pub fn new() -> Self {
        Self::default()
    }

    /// The id for `index`, minting one if this is the first sight of it.
    ///
    /// `parsed` is what llama.cpp reported. A non-empty value is authoritative
    /// and is kept: some formats do carry their own ids, and replacing one would
    /// break the correlation the MODEL made between its call and its arguments.
    pub fn id_for(&mut self, index: u32, parsed: &str) -> String {
        if !parsed.is_empty() {
            // Remembered too, so a later fragment that reports the id as empty
            // (a partial parse can lose it before the call is complete) still
            // resolves to the same value rather than minting a second one.
            return self
                .assigned
                .entry(index)
                .or_insert_with(|| parsed.to_string())
                .clone();
        }
        self.assigned.entry(index).or_insert_with(generate).clone()
    }
}

/// A fresh id.
///
/// Shape follows `llama-server`'s: an opaque token with no structure anyone
/// parses. Uuid rather than a counter because ids reach the persisted
/// transcript, and a per-turn counter would collide across the turns of one
/// session, which is exactly where the orphaned-response failure lives.
fn generate() -> String {
    format!("call_{}", uuid::Uuid::new_v4().simple())
}

#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::expect_used)]
mod tests {
    use super::*;

    #[test]
    fn an_index_keeps_one_id_across_fragments() {
        let mut ids = ToolCallIds::new();
        let first = ids.id_for(0, "");
        assert_eq!(ids.id_for(0, ""), first);
        assert_eq!(
            ids.id_for(0, ""),
            first,
            "the consumer reassembles by index, so a changing id would leave a \
             tool_call_id matching no call",
        );
    }

    #[test]
    fn different_indices_get_different_ids() {
        let mut ids = ToolCallIds::new();
        assert_ne!(ids.id_for(0, ""), ids.id_for(1, ""));
    }

    #[test]
    fn a_generated_id_is_not_empty() {
        // The whole point: an empty id is what garbles the following hops, so
        // "generated" must never mean "generated empty".
        let mut ids = ToolCallIds::new();
        assert!(!ids.id_for(0, "").is_empty());
    }

    #[test]
    fn a_model_supplied_id_wins_and_is_then_remembered() {
        let mut ids = ToolCallIds::new();
        assert_eq!(ids.id_for(0, "call_from_model"), "call_from_model");
        assert_eq!(
            ids.id_for(0, ""),
            "call_from_model",
            "a partial parse that loses the id mid-call must not mint a second",
        );
    }

    #[test]
    fn a_model_supplied_id_does_not_overwrite_one_already_assigned() {
        // Order matters and this is the awkward direction: the call was seen
        // before its id was parsed. The already-streamed id is the one the
        // consumer holds, so it has to win.
        let mut ids = ToolCallIds::new();
        let minted = ids.id_for(0, "");
        assert_eq!(ids.id_for(0, "call_late"), minted);
    }

    #[test]
    fn two_turns_do_not_share_ids() {
        // A fresh `ToolCallIds` per turn is the contract. If a turn reused the
        // previous one, index 0 of turn two would answer with turn one's id and
        // the transcript would carry two calls claiming the same id.
        let mut first = ToolCallIds::new();
        let mut second = ToolCallIds::new();
        assert_ne!(first.id_for(0, ""), second.id_for(0, ""));
    }
}
